        ) {
          throw new Error("상품 검색 응답 형식이 올바르지 않습니다.");
        }

        return data;
      })
      .then((names) => {
        if (!active || requestId !== latestRequest.current) {
          return;
        }

        setProducts(names);
        setError(null);
        setLoading(false);
      })
      .catch((reason: unknown) => {
        if (!active || requestId !== latestRequest.current) {
          return;
        }

        if (reason instanceof DOMException && reason.name === "AbortError") {
          return;
        }

        setProducts([]);
        setError("상품을 불러오지 못했습니다.");
        setLoading(false);
      });

    return () => {
      active = false;
      controller.abort();
    };
  }, [query]);

  return (
    <section>
      <label>
        상품 검색
        <input
          value={query}
          onChange={(event) => setQuery(event.target.value)}
