    def __init__(self):
        self._buffer = bytearray()
        self._failed = False

    def feed(self, data: bytes) -> list[bytes]:
        """수신된 TCP 조각을 추가하고 완성된 payload들을 반환한다."""
        if self._failed:
            raise ValueError("parser is in failed state; call reset() first")

        if not isinstance(data, bytes):
            raise TypeError("data must be bytes")

        self._buffer.extend(data)
        frames: list[bytes] = []

        while True:
            if len(self._buffer) < 4:
                break

            payload_length = int.from_bytes(self._buffer[:4], byteorder="big")
            if payload_length > self.MAX_PAYLOAD:
                self._failed = True
                self._buffer.clear()
                raise ValueError("payload length exceeds 1024 bytes")

            frame_size = 4 + payload_length
            if len(self._buffer) < frame_size:
                break

            payload = bytes(self._buffer[4:frame_size])
            del self._buffer[:frame_size]
            frames.append(payload)

        return frames

    def reset(self) -> None:
        """파서를 새 스트림을 받을 수 있는 초기 상태로 되돌린다."""
